	In this paper, we analyze the global convergence of coordinate gradient descent algorithm for smooth but non-convex optimization problem


\begin{equation}\label{obj-fun}
		\min_{x\in \bR^d} f(x).
	\end{equation}

\begin{algorithm}[H]
		\caption{Randomized coordinate gradient descent}
		\label{alg:random CGD}
		\begin{algorithmic}
			\State Initialization: $x_0\in\bR^d$, $t=0$.
			\While {not convergent}
			\State Draw a coordinate $i_t$ uniformly random from $\{1,2,\dots,d\}$.
			\State Draw a stepsize $\alpha_t$ uniformly random in $[\alpha_{\min},\alpha_{\max}]$.
			\State $x_{t+1}\leftarrow x_t- \alpha_t e_{i_t} \partial_{i_t} f(x_t)$.
			\State $t\leftarrow t+1$.
			\EndWhile
		\end{algorithmic}
	\end{algorithm}

	Let $(\Omega,\mathcal{F},\bP)$ be a probability space and let $\mathbb{T}$ be a semigroup with $\mathcal{B}(\mathbb{T})$ being its Borel $\sigma$-algebra. $\mathbb{T}$ serves as the notion of time. In the setting of Algorithm~\ref{alg:random CGD}, we have $\mathbb{T}=\bN$, corresponding to the one-sided discrete time setting. Other possible examples of $\mathbb{T}$ include $\mathbb{T}=\bZ$, $\mathbb{T}=\bR_{\geq 0}$, and $\mathbb{T}=\bR$, with the assumption that $0\in\mathbb{T}$.


\begin{definition}[Metric dynamical system] A metric dynamical system on a probability space $(\Omega,\mathcal{F},\bP)$ is a family of maps $\{\theta(t):\Omega\rightarrow\Omega\}_{t\in\mathbb{T}}$ satisfying that
		\begin{itemize}
			\item[(i)] The mapping $\mathbb{T}\times\Omega\rightarrow\Omega,\ (t,\omega)\mapsto\theta(t)\omega$ is measurable;

			\item[(ii)] It holds that $\theta(0)=\mathrm{Id}_{\Omega}$ and $\theta(t+s)=\theta(t)\circ\theta(s),\ \forall\ s,t\in\mathbb{T}$;

			\item[(iii)] $\theta(t)$ is $\bP$-preserving for any $t\in\mathbb{T}$, where we say a map $\theta:\Omega\rightarrow\Omega$ is $\bP$-preserving if 
			\begin{equation*}
				\bP(\theta^{-1}B)=\bP(B),\quad \forall\ B\in\mathcal{F}.
			\end{equation*}
		\end{itemize}
	\end{definition}

\begin{definition}[Random dynamical system]
		Let $(X,\mathcal{F}_X)$ be a measurable space and let $\{\theta(t):\Omega\rightarrow\Omega\}_{t\in\mathbb{T}}$ be a metric dynamical system on $(\Omega,\mathcal{F},\bP)$. Then a random dynamical system on $(X,\mathcal{F}_X)$ 
		over $\{\theta(t)\}_{t\in\mathbb{T}}$ is a measurable map 
		\begin{equation*}
			\begin{split}
				\varphi:\mathbb{T}\times\Omega\times X&\rightarrow\quad X,\\
				(t,\omega,x)\ \  & \mapsto \varphi(t,\omega,x),
			\end{split}
		\end{equation*}
		satisfying the following cocycle property: for any $\omega\in\Omega$, $x\in X$, and $s,t\in \mathbb{T}$, it holds that 
		\begin{equation*}
			\varphi(0,\omega,x)=x,
		\end{equation*}
		and that
		\begin{equation}\label{cocycle}
			\varphi(t+s,\omega,x)=\varphi(t,\theta(s)\omega,\varphi(s,\omega,x)).
		\end{equation}
	\end{definition}

	The cocycle property \eqref{cocycle} is a key property of random dynamical system: After time $s$, if we restart the system at $x_s$, the future dynamic corresponds to the sample $\theta(s)\omega$. Note that $\varphi(t,\omega,\cdot)$ is a map on $X$, with some ambiguity of notation, we also use $\varphi(t, \omega)$ to denote this map on $X$ and write $\varphi(t,\omega)x=\varphi(t,\omega,x)$. Then the cocycle property \eqref{cocycle} can be written as 
	\begin{equation*}
		\varphi(t+s,\omega)=\varphi(t,\theta(s)\omega)\circ\varphi(s,\omega).
	\end{equation*}

	In this work, we will focus on the one-sided discrete time $\mathbb{T}=\bN$ and $\theta(t)=\theta^t$, where $\theta$ is $\bP$-preserving and $\theta^t$ is the $t$-fold composition of $\theta$. 
	Suppose that $X=\bR^d$ and $A:\Omega\rightarrow\text{GL}(d,\bR)$ is measurable. Consider a linear random dynamical system defined as (we use $\Phi$ for the linear system, while reserving $\varphi$ for nonlinear dynamics considered later)
	\begin{equation*}
		\Phi(t,\omega)=A(\theta^{t-1}\omega)\cdots A(\theta\omega)A(\omega),
	\end{equation*}
	where the right-hand side is the product of a sequences of random matrices. In this setting, the behavior of the linear system $x_t=\Phi(t,\omega)x_0$ is well understood by the celebrated multiplicative ergodic theorem, also known as the Oseledets theorem, which we recall in Theorem~\ref{thm: MET}. Such type of results was first established by V.I.{} Oseledets~\cite{oseledets} and was further developed in many works such as \cite{raghunathan, Ruelle-1979, Walters-93}.


\begin{theorem}[Multiplicative ergodic theorem, {\cite[Theorem 3.4.1]{Arnold_RDS}}]
		\label{thm: MET}Suppose that 
		\begin{equation*}
			\left(\log\norm{A(\cdot)}\right)_+,\ \left(\log\norm{A(\cdot)^{-1}}\right)_+\in L^1(\Omega,\mathcal{F},\bP),
		\end{equation*}
		where we have used the short-hand $a_+:=\max\{a,0\}$. Then there exists an $\theta$-invariant $\widetilde{\Omega}\in \mathcal{F}$ with $\bP(\widetilde{\Omega})=1$, such that the followings hold for any $\omega\in\widetilde{\Omega}$:
		\begin{itemize}
			\item[(i)] It holds that the limit
			\begin{equation}\label{conv: Lamb}
				\Lambda(\omega)=\lim_{t\rightarrow\infty}\left(\Phi(t,\omega)^{\top}\Phi(t,\omega)\right)^{1/2t},
			\end{equation}
			exists and is a positive definite matrix. Here $\Phi(t, \omega)^{\top}$ denotes the transposition of the matrix (as $\Phi(t, \omega)$ is a linear map on $X$).
			\item[(ii)] Suppose  $\Lambda(\omega)$ has $p(\omega)$ distinct eigenvalues, which are ordered as $e^{\lambda_1(\omega)}>e^{\lambda_2(\omega)}>\cdots> e^{\lambda_{p(\omega)}(\omega)}$. Denote $V_i(\omega)$ the corresponding eigenspace, with dimension $d_i(\omega)$, for  $i=1,2,\dots,p(\omega)$. Then the functions $p(\cdot)$, $\lambda_i(\cdot)$, and $d_i(\cdot)$, $i=1,2,\dots,p(\cdot)$, are all measurable and  $\theta$-invariant on $\widetilde{\Omega}$.
			\item[(iii)] Set $W_i(\omega)=\bigoplus_{j\geq i}V_j(\omega),\ i=1,2,\dots,p(\omega)$,  
			and $W_{p(\omega)+1}(\omega)=\{0\}$. Then it holds that
			\begin{equation}\label{conv: Lya-exp}
				\lim_{t\rightarrow\infty}\frac{1}{t}\log\norm{\Phi(t,\omega)x}=\lambda_i(\omega),\quad\forall\ x\in W_i(\omega)\backslash W_{i+1}(\omega),
			\end{equation}  
			for $i=1,2,\dots,p(\omega)$. The maps $V(\cdot)$ and $W(\cdot)$ from $\widetilde{\Omega}$ to the Grassmannian manifold are measurable. 
			\item[(iv)] It holds that
			\begin{equation*}
				W_i(\theta\omega)=A(\omega)W_i(\omega).
			\end{equation*}
			\item[(v)] When $(\Omega,\mathcal{F},\bP,\theta)$ is ergodic, i.e., every $B\in\mathcal{F}$ with $\theta^{-1}B=B$ satisfies $\bP(B)=0$ or $\bP(B)=1$, the functions  
			$p(\cdot)$, $\lambda_i(\cdot)$, and $d_i(\cdot)$, $i=1,2,\dots,p(\cdot)$, are constant on $\widetilde{\Omega}$.
		\end{itemize}
	\end{theorem}

		\item{\emph{Probability space}.} For each $t \in \bN$, denote  $(\Omega_t,\Sigma_t,\bP_t)$ the usual probability space for the distribution $\mathcal{U}_{\{1,2,\dots,n\}}\times \mathcal{U}_{[\alpha_{\min},\alpha_{\max}]}$, where $\mathcal{U}_{\{1,2,\dots,n\}}$ and $\mathcal{U}_{[\alpha_{\min},\alpha_{\max}]}$ are the uniform distributions on the set $\{1,2,\dots,n\}$ and interval $[\alpha_{\min},\alpha_{\max}]$ respectively. 
		Let $(\Omega,\mathcal{F},\bP)$ be the product probability space of all $(\Omega_t,\Sigma_t,\bP_t),\ t\in\bN$. Denote $\pi_t$ as the projection from $(\Omega,\mathcal{F},\bP)$ onto $(\Omega_t,\Sigma_t,\bP_t), \ t \in \bN$. Thus, a sample $\omega\in\Omega$ can be represented as a sequence  $((i_0,\alpha_0),(i_1,\alpha_1),\dots)$, where $(i_t,\alpha_t)=\pi_t(\omega),\ t\in\bN$. Let $\{\mathcal{F}_t\}_{t\in \bN}$ be the filtration defined by $$\mathcal{F}_t=\sigma\left\{(B_0\times\cdots\times B_t)\times \left(\prod_{j> t}\Omega_j\right):B_i\in \Sigma_i,\ i=0,1,\dots,t\right\}.$$


		\item{\emph{Metric dynamical system}.}
		The metric dynamical system on $\Omega$ is constructed by the (left) shifting operator $\tau:\Omega\rightarrow\Omega$ defined as 
		\begin{equation*}
			\tau(\omega)=\tau(\pi_0(\omega),\pi_1(\omega),\cdots) := (\pi_1(\omega),\pi_2(\omega),\cdots),
		\end{equation*}
		which is clearly measurable and $\bP$-preserving. The metric dynamical system is then given by $\theta(t)=\tau^t$ for $t\in\bN$. 


		\item{\emph{Random dynamical system}.}
		For any $\omega\in\Omega$ and $t\in\bN$, we define $\phi(\omega)$ to be a (nonlinear) map on $\bR^d$ as 
		\begin{equation*}
			\begin{split}
				\phi(\omega):\bR^d&\rightarrow\quad\quad\quad \bR^d\\
				x\ &\mapsto x-\alpha e_i e_i^{\top} \nabla f(x),
			\end{split}
		\end{equation*}
		where $(i,\alpha)=\pi_0(\omega)$ is the first pair/element in the sequence $\omega$, and we define the map $\varphi(t,\omega)$ via 
		\begin{equation*}
			\varphi(t,\omega)=\phi(\tau^{t-1}\omega)\circ\cdots \circ \phi(\tau\omega)\circ \phi(\omega), \qquad \text{for } t \geq 1,
		\end{equation*}
		while $\varphi(0, \omega)$ is the identity operator. It is clear that $\varphi(t,\omega)$ satisfies the cocycle property \eqref{cocycle} and hence defines a random dynamical system on $X=\bR^d$ over $\{\tau^t\}_{t\in\bN}$.
		The iterate of Algorithm~\ref{alg:random CGD} follows the random dynamical system as
		\begin{equation*}
			x_t=\phi(\tau^{t-1}\omega)x_{t-1}=\cdots=\phi(\tau^{t-1}\omega)\circ\cdots \circ \phi(\tau\omega)\circ \phi(\omega)x_0=\varphi(t,\omega)x_0.
		\end{equation*}
		It can be seen that $\{x_t\}_{t\in\bN}$ is $\{\mathcal{F}_t\}$-predictable, i.e., $x_t$ is $\mathcal{F}_{t-1}$-measurable for any $t\in\bNp$, since $x_t$ is determined by samples $(i_0,\alpha_0),(i_1,\alpha_1),\dots,(i_{t-1},\alpha_{t-1})$.


	In our analysis, we will use linearization of the dynamical system $\varphi(t,\omega)$ at a critical point $x^*$ of $f$. Without loss of generality, we assume $x^*=0$; otherwise we consider the system with state being $x-x^*$. The resulting linear system, which depends on $H=\nabla^2 f(x^*)=(H_{ij})_{1\leq i,j\leq d}$, is given by (here and in the sequel, we use the superscript $H$ to indicate dependence on the matrix)
	\begin{equation}\label{linear: Phi}
		\Phi^H(t,\omega)=A^H(\tau^{t-1}\omega)\cdots A^H(\tau\omega)A^H(\omega),
	\end{equation}
	where 
	\begin{equation}\label{linear: A}
		A^H(\omega)=I-\alpha e_i e_i^{\top} H,\quad (i,\alpha)=\pi_0(\omega). 
	\end{equation}
	Note that $A^H(\cdot)$ is bounded in $\Omega$. 
	We know that $\left(\log\norm{A^H(\cdot)}\right)_+$ is integrable. When $\alpha< 1/|H_{ii}|$, 
	the matrix $A^H(\omega)=I-\alpha e_i e_i^{\top} H$ is invertable, and the inverse is given explicitly by applying the Sherman-Morrison formula:
	\begin{equation}\label{inverse-AH}
		\begin{split}
			A^H(\omega)^{-1}&=\left(I-\alpha e_i e_i^{\top} H\right)^{-1} = I + \frac{\alpha e_i e_i^{\top} H}{1 - \alpha H_{ii}}. 
		\end{split}
	\end{equation}
	In particular, we have 
	\begin{equation}
		\norm{A^H(\omega)^{-1}} \leq 1 + \frac{\alpha \norm{H}}{1 - \alpha |H_{ii}|}. 
	\end{equation}
	Thus, if we take the maximal stepsize $\alpha_{\max}$ such that $\alpha_{\max} < 1/\max_{1\leq i\leq d}|H_{ii}|$,  $\norm{A^H(\cdot)^{-1}}$ is bounded in $\Omega$, and as a result $\left(\log\norm{A^H(\cdot)^{-1}}\right)_+$ is also integrable. 
	Therefore, the assumptions of Theorem~\ref{thm: MET} hold. The shifting operator $\tau$ is ergodic on $(\Omega,\mathcal{F},\bP)$ by Kolmogorov's $0$--$1$ law. Then Theorem~\ref{thm: MET} applies for $\theta=\tau$ with $p^H(\cdot)$, $\lambda_i^H(\cdot)$, and $d_i^H(\cdot)$ all being a.e. constant. For any $\omega\in\widetilde{\Omega}$ that is the set in Theorem~\ref{thm: MET} satisfying $\bP(\widetilde{\Omega})=1$, 
	we denote
	\begin{equation}\label{W_pm}
		W_+^H(\omega)=\bigoplus_{\lambda_i>0}V_i^H(\omega),\ \text{and}\ W_-^H(\omega)=\bigoplus_{\lambda_i\leq 0}V_i^H(\omega).
	\end{equation}
	Then the following invariant property holds 
	\begin{equation*}
		W_-^H(\tau\omega)=A^H(\omega)W_-^H(\omega).
	\end{equation*}
	Note that $W_-^H(\omega)$ works as a center-stable subspace. That is, for any $x\in W_-^H(\omega)$ and any $\epsilon>0$, it holds that $\norm{\Phi(t,\omega)x}\leq e^{t\epsilon}$, for sufficiently large $t$, and for $x\notin W_-^H(\omega)$, $\norm{\Phi(t,\omega)x}$ grows exponentially as $t\rightarrow\infty$ with rate greater than $\min_{\lambda_i>0}\lambda_i -\epsilon$ for any $\epsilon>0$.


\begin{assumption}\label{Assump: Hess_bdd} $f \in C^2(\bR^d)$ and the Hessian $\nabla^2 f$ is uniformly bounded, i.e., there exists $M>0$ such that $\norm{\nabla^2 f(x)}\leq M$ for all $x\in\bR^d$.
	\end{assumption}

	An optimization algorithm is expected to converge, under some reasonable assumptions, to a critical point of $f$ where the gradient vanishes. Our aim is to further characterize the possible limits of the algorithm iterates. For this purpose, we distinguish $\calA$, the set of all strict saddle points (including local maxima with non-degenerate Hessian) of $f$:
	\begin{equation*}
		\calA := \{x\in\bR^d:\nabla f(x)=0,\
		\lambda_{\min}(\nabla^2 f(x))<0\},
	\end{equation*}
	where we use the subscript $s$ to emphasize that it is strict. 


\begin{assumption}\label{Assump: non-degenerate}
		For every $x^*\in \calA$, $\nabla^2 f(x^*)$ is non-degenerate, i.e., $x^*$ is a non-degenerate critical point of $f$ in the sense that any eigenvalue of $\nabla^2 f(x^*)$ is nonzero.
	\end{assumption}

\begin{assumption}\label{Assump: non-zero-proj}
		For every $x^*\in \calA$, it holds that $\mathcal{P}_+^H(\omega) e_i\neq 0$, for every $i\in\{1,2,\dots,d\}$ and almost every $\omega\in\Omega$, where $\mathcal{P}_+^H(\omega)$ is the orthogonal projection onto $W_+^H(\omega)$ with $H=\nabla^2 f(x^*)$.
	\end{assumption}

	Given an initial guess $x_0$, the behavior of the algorithm, in particular, the limit of $x_t$, depends on the particular sample $\omega \in \Omega$.
	For any $x^*\in\calA$, we denote the set of all $\omega$ such that the algorithm starting at $x_0$ would converge to $x^*$:
	\begin{equation*}
		\calC(x^*,x_0) :=\left\{\omega\in\Omega:\lim_{t\rightarrow\infty}x_t=\lim_{t\rightarrow\infty}\varphi(t,\omega)x_0=x^*\right\}.
	\end{equation*}
	We further define the set $\calC(\calA,x_0)$ as the union of all $\calC(x^*,x_0)$ over $x^*\in\calA$,
	\begin{equation*}
		\calC(\calA,x_0):=\bigcup_{x^*\in\calA}\calC(x^*,x_0).
	\end{equation*}


	We will first study the linear dynamical system, for which we assume the objective function is given by 


\begin{equation}\label{obj: quadratic}
		f^H(x)=\frac{1}{2}x^{\top} H x,
	\end{equation}

	where $H$ is a symmetric matrix in $\bR^{d\times d}$ with at least one negative eigenvalue. In this case, the coordinate descent algorithm is given by 
	\begin{equation*}
		x_{t+1}=\left(I-\alpha_t e_{i_t} e_{i_t}^{\top} H\right)x_t,
	\end{equation*}
	which corresponds to the linear dynamical system  $\Phi^H(t,\omega)$ with single step map $A^H(\omega)$,  defined in \eqref{linear: Phi} and \eqref{linear: A} respectively. 


	In this subsection, we study the behavior of the nonlinear dynamical system near a strict saddle point of $f$, which without loss of generality can be assumed to be $x^*=0$. As mentioned above, in a small neighborhood of $x^*$, while it is not possible to control the difference between nonlinear and linear systems for infinite time,  the nonlinear system can be approximated by the linear system during a finite time horizon. 


	We first set the small constant $\epsilon$ in Theorem~\ref{thm: local-growth} which controls the failure probability of the amplification bound. Let $\lambda_1>\lambda_2>\cdots>\lambda_p$ be the Lyapunov exponents of the linearized system at $x^*=0$. We set
	\begin{equation}\label{lambplus-gamma}
		\lambda_+=\min_{\lambda_i>0}\lambda_i\quad\text{and}\quad 0<\gamma<\frac{1}{2}\min\left\{\min_{1\leq i< p}|\lambda_i-\lambda_{i+1}|,\lambda_+\right\}. 
	\end{equation}
	Note that $\gamma<\lambda_+$.
	Let $\epsilon_*\in(0,1/6)$ be sufficiently small such that
	\begin{equation}\label{def: eps}
		(1-6\epsilon)(\lambda_+-\gamma)+6\epsilon \cdot \log(1-M\alpha_{\max})>0,\quad \forall\ \epsilon\in(0,\epsilon_*). 
	\end{equation}
	The reason for such choice will become clear later (see \eqref{large S2}). For the rest of the section, we will consider a fixed $\epsilon\in(0,\epsilon_*)$. 


	We now carry out the amplification part of the finite block analysis 
	for the linearized dynamics at $x^* = 0$. To simplify expressions in the following, for $t_1<t_2$, we introduce the short-hand notation
	\begin{equation*}
		(i,\alpha)_{t_1:t_2-1}=\big((i_{t_1},\alpha_{t_1}),\dots,(i_{t_2-1},\alpha_{t_2-1})\big)\in\Omega_{t_1}\times\cdots\times\Omega_{t_2-1},
	\end{equation*}
	and the finite time transition matrix (i.e., composition of linear maps)
	\begin{equation*}
		\Phi^H\bigl((i,\alpha)_{t_1:t_2-1}\bigr)=(I-\alpha_{t_2-1}e_{i_{t_2-1}}e_{i_{t_2-1}}^{\top} H)\cdots (I-\alpha_{t_1} e_{i_{t_1}}e_{i_{t_1}}^{\top} H).
	\end{equation*}
	Recall that $(\Omega_t,\Sigma_t,\bP_t)$ is the probability space for $\mathcal{U}_{\{1,2,\dots,d\}}\times \mathcal{U}_{[\alpha_{\min},\alpha_{\max}]}$ for $t\in\bN$. We also denote $\mathcal{P}_+^H\bigl((i,\alpha)_{t_1:t_2-1}\bigr)$ as the projection operator onto the subspace spanned by the right singular vectors of $\Phi^H\bigl((i,\alpha)_{t_1:t_2-1}\bigr)$ corresponding to $d_+$ largest singular values, where $d_+=\sum_{\lambda_i>0}d_i$ and $d_i$ is the dimension of the $i$-th eigenspace as in Theorem~\ref{thm: MET} (ii) for the linearized system at $x^*$.


	We will then be able to handle $\norm{\mathcal{P}_+^H((i,\alpha)_{0:S-1})e_j}$ using Lemma~\ref{lem: Omega1} and the closeness between $\left(\Phi^H(S,\omega)^{\top} \Phi^H(S,\omega)\right)^{1/2S}$ with $\Lambda(\omega)$ as the former converges to the latter as $S \to \infty$ by Theorem~\ref{thm: MET}. 
	More precisely, denote the singular values of $X\in\bR^{d\times d}$ by $s_1(X)\geq s_2(X)\geq \cdots\geq s_d(X)$. Then for $S\in\bNp$ sufficiently large,
	we have 
	\begin{equation}\label{close: singular value}
		\left|\frac{1}{S}\log s_j\left(\Phi^H(S,\omega)\right)- \lambda_{\mu(j)}\right|=\left|\frac{1}{S}\log s_j\left(\Phi^H\bigl((i,\alpha)_{0:S-1}\bigr)\right)- \lambda_{\mu(j)}\right|\leq \gamma,
	\end{equation}
	for every $j\in\{1,2,\dots,d\}$, where $\lambda_1>\lambda_2>\dots>\lambda_p$ are the Lyapunov exponents from Theorem~\ref{thm: MET}, $\gamma$ is given by \eqref{lambplus-gamma}, and the map $\mu:\{1,2,\dots,d\}\rightarrow\{1,2,\dots,p\}$ satisfies that $\mu(j)=i$ if and only if $d_1+\cdots +d_{i-1}<j\leq d_1+\cdots +d_i$, so $\mu$ corresponds the index for the singular values with that of the Lyapunov exponents. 
	Moreover,
	the convergence also implies that 
	\begin{equation*}
		\norm{\mathcal{P}_+^H(S,\omega)-\mathcal{P}_+^H(\omega)}\leq\frac{\delta}{2},
	\end{equation*}
	for sufficiently large $S$, which then leads to
	\begin{equation}\label{close: singular space}
		\norm{\mathcal{P}^H_+\left(S,\omega\right)e_j}=\norm{\mathcal{P}^H_+\left((i,\alpha)_{0:S-1}\right)e_j}\geq \frac{\delta}{2},
	\end{equation}
	for every $j\in\{1,2,\dots,d\}$,
	where $\mathcal{P}^H_+(S,\omega)$ is the projection operator onto the subspace spanned by the right singular vectors of $\Phi^H(S,\omega)$ corresponding to $d_+$ largest singular values. Let 
	\begin{equation}
		\Omega^S=\bigl\{(i,\alpha)_{0:S-1}\in \Omega_0\times\cdots\times\Omega_{S-1}:\eqref{close: singular value}\text{ and }\eqref{close: singular space}\text{ hold}\bigr\}.
	\end{equation}
	The following lemma states that $\Omega^S$ has high probability for sufficiently large $S$, where with slight abuse of notation, we write $\bP(\Omega^S)=\bP\left(\Omega^S\times\left(\bigtimes_{t\geq S}\Omega_t\right)\right)$.


	Note that $\alpha_{\varrho_t-1}\sim\mathcal{U}_{[\alpha_{\min},\alpha_{\max}]}$ is independent of $\mathcal{F}_{\varrho_t-2}$, $i_{\varrho_t-1}$, and $(i,\alpha)_{\varrho_t:\varrho_t+S-1}$. 
	The next lemma shows that with high probability, the choice of $\alpha_{\varrho_t-1}$ will lead to a nontrivial orthogonal projection of $x_{\varrho_t}$ onto the unstable subspace of $\Phi^H(S,\tau^{\varrho_t}\omega)=\Phi^H\bigl((i,\alpha)_{\varrho_t:\varrho_t+S-1}\bigr)$.

