		\end{equation}
	\end{definition}

The cocycle property \eqref{cocycle} is a key property of random dynamical system: After time $s$, if we restart the system at $x_s$, the future dynamic corresponds to the sample $\theta(s)\omega$. Note that $\varphi(t,\omega,\cdot)$ is a map on $X$, with some ambiguity of notation, we also use $\varphi(t, \omega)$ to denote this map on $X$ and write $\varphi(t,\omega)x=\varphi(t,\omega,x)$. Then the cocycle property \eqref{cocycle} can be written as 
\begin{equation*}
	\varphi(t+s,\omega)=\varphi(t,\theta(s)\omega)\circ\varphi(s,\omega).
\end{equation*}

In this work, we will focus on the one-sided discrete time $\mathbb{T}=\bN$ and $\theta(t)=\theta^t$, where $\theta$ is $\bP$-preserving and $\theta^t$ is the $t$-fold composition of $\theta$. 
Suppose that $X=\bR^d$ and $A:\Omega\rightarrow\text{GL}(d,\bR)$ is measurable. Consider a linear random dynamical system defined as (we use $\Phi$ for the linear system, while reserving $\varphi$ for nonlinear dynamics considered later)
\begin{equation*}
	\Phi(t,\omega)=A(\theta^{t-1}\omega)\cdots A(\theta\omega)A(\omega),
\end{equation*}
where the right-hand side is the product of a sequences of random matrices. In this setting, the behavior of the linear system $x_t=\Phi(t,\omega)x_0$ is well understood by the celebrated multiplicative ergodic theorem, also known as the Oseledets theorem, which we recall in Theorem~\ref{thm: MET}. Such type of results was first established by V.I.{} Oseledets~\cite{oseledets} and was further developed in many works such as \cite{raghunathan, Ruelle-1979, Walters-93}.

\begin{theorem}[Multiplicative ergodic theorem, {\cite[Theorem 3.4.1]{Arnold_RDS}}]
		\label{thm: MET}Suppose that 
		\begin{equation*}
			\left(\log\norm{A(\cdot)}\right)_+,\ \left(\log\norm{A(\cdot)^{-1}}\right)_+\in L^1(\Omega,\mathcal{F},\bP),
		\end{equation*}
		where we have used the short-hand $a_+:=\max\{a,0\}$. Then there exists an $\theta$-invariant $\widetilde{\Omega}\in \mathcal{F}$ with $\bP(\widetilde{\Omega})=1$, such that the followings hold for any $\omega\in\widetilde{\Omega}$:
		\begin{itemize}
			\item[(i)] It holds that the limit
			\begin{equation}\label{conv: Lamb}
				\Lambda(\omega)=\lim_{t\rightarrow\infty}\left(\Phi(t,\omega)^{\top}\Phi(t,\omega)\right)^{1/2t},
			\end{equation}
			exists and is a positive definite matrix. Here $\Phi(t, \omega)^{\top}$ denotes the transposition of the matrix (as $\Phi(t, \omega)$ is a linear map on $X$).
			\item[(ii)] Suppose  $\Lambda(\omega)$ has $p(\omega)$ distinct eigenvalues, which are ordered as $e^{\lambda_1(\omega)}>e^{\lambda_2(\omega)}>\cdots> e^{\lambda_{p(\omega)}(\omega)}$. Denote $V_i(\omega)$ the corresponding eigenspace, with dimension $d_i(\omega)$, for  $i=1,2,\dots,p(\omega)$. Then the functions $p(\cdot)$, $\lambda_i(\cdot)$, and $d_i(\cdot)$, $i=1,2,\dots,p(\cdot)$, are all measurable and  $\theta$-invariant on $\widetilde{\Omega}$.
			\item[(iii)] Set $W_i(\omega)=\bigoplus_{j\geq i}V_j(\omega),\ i=1,2,\dots,p(\omega)$,  
			and $W_{p(\omega)+1}(\omega)=\{0\}$. Then it holds that
			\begin{equation}\label{conv: Lya-exp}
				\lim_{t\rightarrow\infty}\frac{1}{t}\log\norm{\Phi(t,\omega)x}=\lambda_i(\omega),\quad\forall\ x\in W_i(\omega)\backslash W_{i+1}(\omega),
			\end{equation}  
			for $i=1,2,\dots,p(\omega)$. The maps $V(\cdot)$ and $W(\cdot)$ from $\widetilde{\Omega}$ to the Grassmannian manifold are measurable. 
			\item[(iv)] It holds that
			\begin{equation*}
				W_i(\theta\omega)=A(\omega)W_i(\omega).
			\end{equation*}
			\item[(v)] When $(\Omega,\mathcal{F},\bP,\theta)$ is ergodic, i.e., every $B\in\mathcal{F}$ with $\theta^{-1}B=B$ satisfies $\bP(B)=0$ or $\bP(B)=1$, the functions  
			$p(\cdot)$, $\lambda_i(\cdot)$, and $d_i(\cdot)$, $i=1,2,\dots,p(\cdot)$, are constant on $\widetilde{\Omega}$.
		\end{itemize}
	\end{theorem}

\item{\emph{Metric dynamical system}.}
The metric dynamical system on $\Omega$ is constructed by the (left) shifting operator $\tau:\Omega\rightarrow\Omega$ defined as 
\begin{equation*}
	\tau(\omega)=\tau(\pi_0(\omega),\pi_1(\omega),\cdots) := (\pi_1(\omega),\pi_2(\omega),\cdots),
\end{equation*}
which is clearly measurable and $\bP$-preserving. The metric dynamical system is then given by $\theta(t)=\tau^t$ for $t\in\bN$.

\item{\emph{Random dynamical system}.}
For any $\omega\in\Omega$ and $t\in\bN$, we define $\phi(\omega)$ to be a (nonlinear) map on $\bR^d$ as 
\begin{equation*}
	\begin{split}
		\phi(\omega):\bR^d&\rightarrow\quad\quad\quad \bR^d\\
		x\ &\mapsto x-\alpha e_i e_i^{\top} \nabla f(x),
	\end{split}
\end{equation*}
where $(i,\alpha)=\pi_0(\omega)$ is the first pair/element in the sequence $\omega$, and we define the map $\varphi(t,\omega)$ via 
\begin{equation*}
	\varphi(t,\omega)=\phi(\tau^{t-1}\omega)\circ\cdots \circ \phi(\tau\omega)\circ \phi(\omega), \qquad \text{for } t \geq 1,
\end{equation*}
while $\varphi(0, \omega)$ is the identity operator. It is clear that $\varphi(t,\omega)$ satisfies the cocycle property \eqref{cocycle} and hence defines a random dynamical system on $X=\bR^d$ over $\{\tau^t\}_{t\in\bN}$.
The iterate of Algorithm~\ref{alg:random CGD} follows the random dynamical system as
\begin{equation*}
	x_t=\phi(\tau^{t-1}\omega)x_{t-1}=\cdots=\phi(\tau^{t-1}\omega)\circ\cdots \circ \phi(\tau\omega)\circ \phi(\omega)x_0=\varphi(t,\omega)x_0.
\end{equation*}
It can be seen that $\{x_t\}_{t\in\bN}$ is $\{\mathcal{F}_t\}$-predictable, i.e., $x_t$ is $\mathcal{F}_{t-1}$-measurable for any $t\in\bNp$, since $x_t$ is determined by samples $(i_0,\alpha_0),(i_1,\alpha_1),\dots,(i_{t-1},\alpha_{t-1})$.

In our analysis, we will use linearization of the dynamical system $\varphi(t,\omega)$ at a critical point $x^*$ of $f$. Without loss of generality, we assume $x^*=0$; otherwise we consider the system with state being $x-x^*$. The resulting linear system, which depends on $H=\nabla^2 f(x^*)=(H_{ij})_{1\leq i,j\leq d}$, is given by (here and in the sequel, we use the superscript $H$ to indicate dependence on the matrix)
\begin{equation}\label{linear: Phi}
	\Phi^H(t,\omega)=A^H(\tau^{t-1}\omega)\cdots A^H(\tau\omega)A^H(\omega),
\end{equation}
where 
\begin{equation}\label{linear: A}
	A^H(\omega)=I-\alpha e_i e_i^{\top} H,\quad (i,\alpha)=\pi_0(\omega). 
\end{equation}
Note that $A^H(\cdot)$ is bounded in $\Omega$. 
We know that $\left(\log\norm{A^H(\cdot)}\right)_+$ is integrable. When $\alpha< 1/|H_{ii}|$, 
the matrix $A^H(\omega)=I-\alpha e_i e_i^{\top} H$ is invertable, and the inverse is given explicitly by applying the Sherman-Morrison formula:
\begin{equation}\label{inverse-AH}
	\begin{split}
		A^H(\omega)^{-1}&=\left(I-\alpha e_i e_i^{\top} H\right)^{-1} = I + \frac{\alpha e_i e_i^{\top} H}{1 - \alpha H_{ii}}. 
	\end{split}
\end{equation}
In particular, we have 
\begin{equation}
	\norm{A^H(\omega)^{-1}} \leq 1 + \frac{\alpha \norm{H}}{1 - \alpha |H_{ii}|}. 
\end{equation}
Thus, if we take the maximal stepsize $\alpha_{\max}$ such that $\alpha_{\max} < 1/\max_{1\leq i\leq d}|H_{ii}|$,  $\norm{A^H(\cdot)^{-1}}$ is bounded in $\Omega$, and as a result $\left(\log\norm{A^H(\cdot)^{-1}}\right)_+$ is also integrable. 
Therefore, the assumptions of Theorem~\ref{thm: MET} hold. The shifting operator $\tau$ is ergodic on $(\Omega,\mathcal{F},\bP)$ by Kolmogorov's $0$--$1$ law. Then Theorem~\ref{thm: MET} applies for $\theta=\tau$ with $p^H(\cdot)$, $\lambda_i^H(\cdot)$, and $d_i^H(\cdot)$ all being a.e. constant. For any $\omega\in\widetilde{\Omega}$ that is the set in Theorem~\ref{thm: MET} satisfying $\bP(\widetilde{\Omega})=1$, 
we denote
\begin{equation}\label{W_pm}
	W_+^H(\omega)=\bigoplus_{\lambda_i>0}V_i^H(\omega),\ \text{and}\ W_-^H(\omega)=\bigoplus_{\lambda_i\leq 0}V_i^H(\omega).
\end{equation}
Then the following invariant property holds 
\begin{equation*}
	W_-^H(\tau\omega)=A^H(\omega)W_-^H(\omega).
\end{equation*}
Note that $W_-^H(\omega)$ works as a center-stable subspace. That is, for any $x\in W_-^H(\omega)$ and any $\epsilon>0$, it holds that $\norm{\Phi(t,\omega)x}\leq e^{t\epsilon}$, for sufficiently large $t$, and for $x\notin W_-^H(\omega)$, $\norm{\Phi(t,\omega)x}$ grows exponentially as $t\rightarrow\infty$ with rate greater than $\min_{\lambda_i>0}\lambda_i -\epsilon$ for any $\epsilon>0$.

 egin{assumption}\label{Assump: Hess_bdd} $f \in C^2( R^d)$ and the Hessian $
abla^2 f$ is uniformly bounded, i.e., there exists $M>0$ such that $
