\begin{proposition}\label{prop: posi-lamb1}
		%For any $x^*\in\calA$, if 
		Let $H$ have a negative eigenvalue and
		$0<\alpha_{\min}<\alpha_{\max}<1/\max_{1\leq i\leq d}|H_{ii}|$, then the largest Lyapunov exponent of $\Phi^H(t,\omega)$ is positive. 
	\end{proposition}

\begin{proposition}\label{prop: linear_decay}
		Let $m\geq d$ be fixed. For the objective function \eqref{obj: quadratic} with $\lambda_{\min}(H)<0$, suppose 
		that $0<\alpha_{\min}<\alpha_{\max}<1/\max_{1\leq i\leq d}|H_{ii}|$, there exists $c\in(0,1)$ depending on $m$, $H$, $\alpha_{\min}$, and $\alpha_{\max}$, 
		such that 
		\begin{equation*}
			f^H(x_{t+m})-f^H(x_t)\leq c\, f^H(x_t),
		\end{equation*}
		holds as long as $f^H(x_t)<0$ and $\{1,2,\dots,d\}=\{i_t,i_{t+1},\dots,i_{t+m-1}\}$ (in the sense of sets). 
	\end{proposition}

\begin{proof} 
		Without loss of generality, we assume that $t=0$. 
		Due to the choice of $\alpha_{\max}$, we have the following simple non-increasing property for any $t'\in\bN$:
		\begin{equation}\label{decay: quad}
			\begin{split}
				f^H(x_{t'+1})&=\frac{1}{2}x_{t'+1}^{\top} H x_{t'+1}\\
				&=\frac{1}{2}x_{t'}^{\top} \left(I-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H\right)^{\top} H \left(I-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H\right) x_{t'}\\
				&=f^H(x_{t'})-\alpha_{t'} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2+\frac{1}{2}\alpha_t^2 e_{i_{t'}}^{\top} H e_{i_{t'}} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2\\
				&\leq f^H(x_{t'})-\frac{\alpha_{t'}}{2} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2.
			\end{split}
		\end{equation}

		Write $x_0=y^*+y_0$ with $y^*\in\ker(H)$ and $y_0\in\ran(H)$. Let 
		\begin{equation}
			\label{def: y}
			y_{t'+1}=y_{t'}-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H y_{t'}, \qquad t'=0,1,\dots,m-1.
		\end{equation} 
		Then $x_{t'}=y^*+y_{t'}$ holds for any $t'=0,1,\dots,m$. Using \eqref{decay: quad}, to give an upper bound for $f^H(x_{t+m})-f^H(x_t)$, we would like a nontrivial lower bound for $\alpha_{t'}\bigl(e_{i_{t'}}^{\top} H x_{t'}\bigr)^2=\alpha_{t'}\bigl(e_{i_{t'}}^{\top} H y_{t'}\bigr)^2$ for some $t'\in\{t,t+1,\dots,t+m-1\}$, which is guaranteed by Lemma~\ref{lem: linear_decay}, whose proof will be postponed. 

		\begin{lemma} \label{lem: linear_decay}
			Suppose that $\{1,2,\dots,d\}=\{i_0,i_1,\dots,i_{m-1}\}$. For any
			\begin{equation}\label{def:delta}
				0<\delta\leq\min\left\{\frac{1}{2m},\frac{\alpha_{\min}\sigma_{\min}(H)}{2\sqrt{m}(m\alpha_{\max}\sigma_{\max}(H)+1)}\right\},
			\end{equation}
			where $\sigma_{\min}(H)$ and $\sigma_{\max}(H)$ are the smallest and largest positive singular values of $H$ respectively, 
			if $0\neq y_0\in \ran(H)$, then there exists $T\in \{0,1,\dots,m-1\}$ such that $\alpha_{T}\left\vert e_{i_{T}}^{\top} H y_{T}\right\vert\geq \delta\norm{y_{T}}$, where the sequence $y_t$ is given as in \eqref{def: y}. 
		\end{lemma}

		Assuming the lemma, there exists $T\in\{0,1,\dots,m-1\}$ that 
		\begin{equation*}
			\alpha_T\left\vert e_{i_{T}}^{\top} H y_{T}\right\vert\geq \delta\norm{y_{T}},
		\end{equation*}
		with a fixed $\delta>0$ satisfying \eqref{def:delta}. We can further constrain that $\frac{\delta^2}{\alpha_{\min}\sigma_{\max}(H)}<1$. Thus, we have
		\begin{equation*}\label{decay esti}
			\begin{split}
				f^H(x_m)&\leq f^H (x_{T+1})\leq f^H(x_T)- \frac{\alpha_T}{2}\left(e_{i_{T}}^{\top} H x_{T}\right)^2\leq f^H (x_{T}) -\frac{\delta^2}{2\alpha_T}\norm{y_{T}}^2,
			\end{split}
		\end{equation*}
		which combined with $\sigma_{\max}(H)\norm{y_{T}}^2\geq -y_{T}^{\top} H y_{T}=-x_{T}^{\top} H x_{T}=-2f^H(x_T)$,
		yields that 
		\begin{equation*}
			f^H (x_m) \leq\left( 1 +\frac{\delta^2}{\alpha_T \sigma_{\max}(H)}\right)f^H (x_{T}) \leq\left( 1 +\frac{\delta^2}{\alpha_T \sigma_{\max}(H)}\right)f^H (x_0). 
		\end{equation*}
		Set $c=\frac{\delta^2}{\alpha_{\max} \sigma_{\max}(H)}$ and we get that $f^H(x_m)-f^H(x_0)\leq c f^H(x_0)$.
	\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem: linear_decay}] Suppose on the contrary that $\alpha_t\left\vert e_{i_t}^{\top} H y_t\right\vert< \delta\norm{y_t}$ for any $t\in \{0,1,\dots,m-1\}$. It holds that
		\begin{equation*}
			\norm{y_1-y_0}=\alpha_0\left\vert e_{i_0}^{\top} H y_0\right\vert<\delta\norm{y_0}<2\delta\norm{y_0}.
		\end{equation*}
		We claim that 
		\begin{equation} \label{eq: disty}
			\norm{y_t-y_0}<2 t\delta\norm{y_0},
		\end{equation}
		for any $t=1,2,\dots,m-1$. By induction, assume that  $\norm{y_t-y_0}<2t\delta\norm{y_0}$ holds for some $t\in\{1,2,\dots,m-2\}$, then 
		\begin{equation*}
			\norm{y_{t+1}-y_t}=\alpha_t\left\vert e_{i_t}^{\top} H y_t\right\vert< \delta\norm{y_t}<\delta(2t\delta+1)\norm{y_0}<2\delta\norm{y_0},
		\end{equation*}
		where the last inequality uses $2 t \delta < 2m \delta \leq 1 $. It follows $\norm{y_{t+1}-y_0}\leq \norm{y_t-y_0}+\norm{y_{t+1}-y_t}<2(t+1)\delta\norm{y_0}$.

		Using \eqref{eq: disty} and $\max_{1\leq i\leq d} \norm{H e_i}\leq \sigma_{\max}(H)$, we have 
		\begin{equation*}
			\begin{split}
				\alpha_t\bigl\lvert e_{i_t}^{\top} H y_0\bigr\rvert&\leq \alpha_t\bigl\lvert e_{i_t}^{\top} H (y_t-y_0)\bigr\rvert+\alpha_t\bigl\lvert e_{i_t}^{\top} H y_t\bigr\rvert\\
				&<\alpha_{\max}\sigma_{\max}(H)\cdot 2 t\delta\norm{y_0}+2\delta\norm{y_0}\\
				&<2\delta(m\alpha_{\max}\sigma_{\max}(H)+1)\norm{y_0},
			\end{split}
		\end{equation*}
		for $t=0,1,\dots,m-1$. Since $\text{span}\{e_{i_k}:k=0,1,\dots,m-1\}=\bR^d$, noticing that $y_0\in\ran{H}$, we have
		\begin{equation*}
			\begin{split}
				\alpha_{\min}\sigma_{\min}(H) \norm{y_0}&\leq \alpha_{\min}\norm{H y_0}\leq\left(\sum_{t=0}^{m-1} \left(\alpha_t\bigl\lvert e_{i_t}^{\top} H y_0\bigr\rvert\right)^2\right)^{1/2}\\
				& <2\delta\sqrt{m}(m\alpha_{\max}\sigma_{\max}(H)+1)\norm{y_0},
			\end{split}
		\end{equation*}
		which contradicts with the choice of $\delta$ in \eqref{def:delta}.
	\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop: posi-lamb1}] It suffices to show that for almost every $\omega\in\Omega$ there exist some $x_0\in \bR^d$, $\epsilon>0$, and $T>0$, such that $x_t=\Phi(t,\omega)x_0$ satisfies $\norm{x_t}\geq e^{\epsilon t}$ for any $t>T$. Let $x_0$ be an eigenvector corresponding to a negative eigenvalue of $H$. Then it holds that $f^H(x_0)< 0$. Consider a fixed $m\geq d$. For any $k\in\bN$, set $I_k=1$ if $\{1,2,\dots,d\}=\{i_{km},i_{km+1},\dots,i_{km+m-1}\}$ 
		and $I_k=0$ otherwise. We can see that the random variables, $I_0,I_1,I_2,\dots$, are independent and identically distributed with $\bE I_0=\bP(I_0=1)\in(0,1)$. By Proposition~\ref{prop: linear_decay}, we obtain that
		\begin{equation*}
			f^H(x_{(k+1)m})\leq\begin{cases}
				(1+c)f^H(x_{km}),&\text{if }I_k=1,\\
				f^H(x_{km}),&\text{if }I_k=0,
			\end{cases}
		\end{equation*}	
		where $c$ is the constant from Proposition~\ref{prop: linear_decay}.
		Therefore, %\jl{missing $1/2$}
		\begin{equation*}
			\frac{\lambda_{\min}(H)}{2}\norm{x_{km}}^2\leq f^H(x_{km})\leq(1+c)^{\sum_{j=0}^{k-1} I_j}f^H(x_0),
		\end{equation*}
		which implies that
		\begin{equation}\label{norm:xkm}
			\norm{x_{km}}\geq \left(\frac{2f^H(x_0)}{\lambda_{\min}(H)}\right)^{1/2}\cdot (1+c)^{\frac{1}{2}\sum_{j=0}^{k-1} I_j}.
		\end{equation}
		Note that $\bE |I_0|=\bE I_0<\infty$. The strong law of large number suggests that for almost every $\omega\in\Omega$, there exists some $K$, such that for all $k \geq K$
		\begin{equation}\label{SLLN}
			\sum_{j=0}^{k-1} I_j\geq \frac{\bE I_0}{2}k.
		\end{equation}
		Combining \eqref{norm:xkm} and \eqref{SLLN}, we arrive at
		\begin{equation*}
			\norm{x_{km}}\geq \left(\frac{2f^H(x_0)}{\lambda_{\min}(H)}\right)^{1/2}\cdot (1+c)^{\frac{\bE I_0}{4m}\cdot km}.
		\end{equation*}
		Noticing that $(1+c)^{\frac{\bE I_0}{4m}}$ is greater than $1$, $\norm{x_{km}}$ grows exponentially in $km$ and we complete the proof.
	\end{proof}

\begin{theorem}\label{thm: local-growth}
		Suppose that Assumptions~\ref{Assump: Hess_bdd}, \ref{Assump: non-degenerate}, and \ref{Assump: non-zero-proj} hold and that $0<\alpha_{\min}<\alpha_{\max}<1/M$. There exists $\epsilon_*\in(0,1/6)$ such that for any $\epsilon\in(0,\epsilon_*)$, we have $T_* = T_*(\epsilon) \in\bNp$ that for any $T \in \bNp$ with $T\geq T_*$ and any $t\in\bN$, conditioned on $\mathcal{F}_{t-1}$, with probability at least $1-4\epsilon$, it holds for all $x_t \in V$ that
		\begin{equation}\label{local-growth}
			\norm{x_{t+T}}\geq \exp\biggl(\frac{6\epsilon}{1 - 6 \epsilon} \bigl\lvert \log(1-M\alpha_{\max}) \bigr\rvert \, T\biggr) \norm{x_t},
		\end{equation}
		where $V$ is a neighborhood of $x^* = 0$, depending on $\epsilon$, $T$, and $f$ near $x^*$. 
	\end{theorem}

\begin{lemma}\label{lem: L}
		Let $0<\mu\leq\frac{1}{\sqrt{d}}$ be a fixed constant. 
		There exists some constant $L>0$, such that for any $t\in\bN$, there exists a measurable $\varrho_t:\Omega\rightarrow \bNp$ such that $t < \varrho_t \leq t + L$ and
		\begin{equation}\label{eq: rho_t}
			\bP\Bigl(\bigl\lvert e_{i_{\varrho_t-1}}^{\top} \nabla f(x_{\varrho_t-1})\bigr\rvert \geq \mu\norm{\nabla f(x_{\varrho_t-1})}\;\Big\vert\; \mathcal{F}_{t-1}\Bigr)\geq 1-\epsilon.
		\end{equation}
	\end{lemma}

\begin{proof}
		For any $t\in\bN$, use $\ell_0$ to denote the smallest non-negative integer $\ell$, such that
		\begin{equation*}
			\ell_0 = \arg\min_{\ell} \Bigl\{ \ell \in \mathbb{N}_+ \,:\,	\bigl\lvert e_{i_{t+\ell-1}}^{\top} \nabla f(x_{t+\ell-1})\bigr\rvert\geq \mu\norm{\nabla f(x_{t+\ell-1})} \Bigr\}.
		\end{equation*}
		It is clear that $\bP(\ell_0 >\ell\mid\mathcal{F}_{t-1})\leq (1-1/d)^\ell$, since for each step the coordinate is randomly chosen. Hence, there exists some $L>0$, such that 
		\begin{equation*}
			\bP(\ell_0 \leq L\mid\mathcal{F}_{t-1})\geq 1-\epsilon.
		\end{equation*}
		We finish the proof by setting $\varrho_t = t + \min\{ \ell_0, L \}$
		which has the desired property. 
	\end{proof}

\begin{lemma}\label{lem: Omega1}
		Under Assumption~\ref{Assump: non-zero-proj}, 
		there exist $\delta>0$ and measurable $\Omega_1^\epsilon\subset\widetilde{\Omega}$, where $\widetilde{\Omega}$ is from Theorem~\ref{thm: MET}, 
		such that $\bP(\Omega_1^\epsilon)\geq 1-\epsilon$ 
		and 
		\begin{equation*}
			\norm{\mathcal{P}^H_+(\omega) e_i}\geq\delta,\quad \forall\ \omega\in\Omega_1^\epsilon,\ i\in\{1,2,\dots,d\}.
		\end{equation*}
	\end{lemma}

\begin{proof}
		Assumption~\ref{Assump: non-zero-proj} implies that 
		\begin{equation*}
			\bP\bigl(\{\omega\in\widetilde{\Omega}:\norm{\mathcal{P}^H_+(\omega) e_i}>0,\quad \forall\ i\in\{1,2,\dots,d\}\}\bigr) = 1
		\end{equation*}
		Notice that 
		\begin{multline*}
			\bigl\{\omega\in\widetilde{\Omega}:\norm{\mathcal{P}^H_+(\omega) e_i}>0,\quad \forall\ i\in\{1,2,\dots,d\}\bigr\}
			= \\ 
			=\bigcup_{n\in\bNp}\Bigl\{\omega\in\widetilde{\Omega}:\norm{\mathcal{P}^H_+(\omega) e_i}\geq \frac{1}{n},\quad \forall\ i\in\{1,2,\dots,d\}\Bigr\}.
		\end{multline*}
		The Lemma follows from continuity of measure. 
	\end{proof}

\begin{lemma}\label{lem: T-Omega2}
		Under the same assumptions of Lemma~\ref{lem: Omega1}, there exists some $S_*>0$, such that for every $S \in \bNp, S \geq S_*$, it holds $\bP(\Omega^S)\geq 1-2\epsilon$.
	\end{lemma}

\begin{proof}
		For $a.e.\ \omega\in\Omega$, it follows from Theorem~\ref{thm: MET}, in particular \eqref{conv: Lamb}, and standard matrix perturbation analysis (see e.g., \cite[Theorem VI.2.1, Theorem VII.3.1]{bhatia}) that 
		\begin{equation}\label{conv_lya_component}
			\frac{1}{S}s_j(\Phi^H(S,\omega))\rightarrow\lambda_{\mu(j)},\quad S\rightarrow\infty.
		\end{equation}
		for any $j\in\{1,2,\dots,d\}$, and that
		\begin{equation}\label{conv_subspace}
			\mathcal{P}^H_+(S,\omega)\rightarrow\mathcal{P}^H_+(\omega),\quad S\rightarrow\infty.
		\end{equation}

		By Egorov's theorem, there exists $\Omega_2^\epsilon\subset\Omega_1^\epsilon$ with $\bP(\Omega_2^\epsilon) \geq 1 - 2 \epsilon$, such that the convergences in \eqref{conv_lya_component} and \eqref{conv_subspace} are both uniform on $\Omega_2^\epsilon$. Here $\Omega_1^\epsilon$ is as in Lemma~\ref{lem: Omega1}. Therefore, for some $S_*$ sufficiently large, we have
		\begin{equation*}\label{uniconv: singval}
			\left|\frac{1}{S}\log s_j\left(\Phi^H(S,\omega)\right)- \lambda_{\mu(j)}\right|\leq \gamma,\quad\forall\ j\in\{1,2,\dots,d\},\ S\geq S_*,\ \omega\in\Omega_2^\epsilon,
		\end{equation*}
		and
		\begin{equation}\label{uniconv: singspace}
			\norm{\mathcal{P}^H_+(S,\omega)-\mathcal{P}^H_+(\omega)}\leq \frac{\delta}{2},\quad\forall\ S\geq S_*,\ \omega\in\Omega_2^\epsilon.
		\end{equation}
		Combining Lemma~\ref{lem: Omega1} and \eqref{uniconv: singspace}, we obtain that
		\begin{equation*}
			\norm{\mathcal{P}^H_+(S,\omega)e_i}\geq \frac{\delta}{2},\quad \forall\ i\in\{1,2,\dots,d\},\ \forall\ S\geq S_*,\ \omega\in\Omega_2^\epsilon.
		\end{equation*}

		For any $S\geq S_*$, 
		by the definition of $\Omega^S$, it holds that 
		\begin{equation*}
			\Omega_2^\epsilon\subset\Omega^S\times\Bigl(\bigtimes_{t\geq S}\Omega_t\Bigr),
		\end{equation*}
		which implies the desired estimate 
		\begin{equation*}
			\bP(\Omega^S)=\bP\biggl(\Omega^S\times\Bigl(\bigtimes_{t\geq S}\Omega_t\Bigr)\biggr)\geq\bP(\Omega_2^\epsilon)\geq 1-2\epsilon. %\qedhere
		\end{equation*}
	\end{proof}

\begin{lemma}\label{lem: nontrial-proj}
		For any $S\in\bNp$, $x_{\varrho_t-1}$, $i_{\varrho_t-1}$, 
		and $(i,\alpha)_{\varrho_t:\varrho_t+S-1} \in\Omega^S$, there exists $I\subset[\alpha_{\min},\alpha_{\max}]$ with $m(I)\geq (1-\epsilon)(\alpha_{\max}-\alpha_{\min})$ where $m(\cdot)$ is the Lebesgue measure,  such that for any $\alpha_{\varrho_t-1}\in I$, it holds that 
		\begin{equation}\label{eq: nontrial-proj}
			\norm{\mathcal{P}^H_+\left((i,\alpha)_{\varrho_t:\varrho_t+S-1}\right)x_{\varrho_t}}\geq \frac{\epsilon\delta (\alpha_{\max}-\alpha_{\min})}{4}\bigl\lvert e_{i_{\varrho_t-1}}^{\top} \nabla f(x_{\varrho_t-1})\bigr\rvert.
		\end{equation}
	\end{lemma}

\begin{proof}
		We assume that $\bigl\lvert e_{i_{\varrho_t-1}}^{\top} \nabla f(x_{\varrho_t-1})\bigr\rvert\neq 0$; otherwise the result is trivial. 

		For simplicity of notation, we write 
		\begin{equation*}
			\begin{aligned}
				\mathcal{P}^H_+\left((i,\alpha)_{\varrho_t:\varrho_t+S-1}\right)x_{\varrho_t} & = 
				\mathcal{P}^H_+\left((i,\alpha)_{\varrho_t:\varrho_t+S-1}\right)x_{\varrho_t-1} \\
				& \qquad 
				- \alpha_{\varrho_t - 1} e_{i_{\varrho_t-1}}^{\top}\nabla f(x_{\varrho_t-1})\mathcal{P}^H_+\left((i,\alpha)_{\varrho_t:\varrho_t+S-1}\right)e_{i_{\varrho_t-1}} \\
				& =: y_2-\alpha_{\varrho_t-1} y_1,
			\end{aligned}
		\end{equation*}
		where the last line defines $y_1$ and $y_2$. Using the short-hand notation 
		\begin{equation*}
			r=\frac{\epsilon\delta (\alpha_{\max}-\alpha_{\min})}{4}\bigl\lvert e_{i_{\varrho_t-1}}^{\top} \nabla f(x_{\varrho_t-1})\bigr\rvert, 
		\end{equation*}
		we observe then \eqref{eq: nontrial-proj} holds if and only if $\alpha_{\varrho_t-1} y_1$ is not located in a ball with radius $r$ centered at $y_2$.

		It follows from the definition of $\Omega^S$ and \eqref{close: singular space} that $ \norm{\mathcal{P}^H_+\left((i,\alpha)_{\varrho_t:\varrho_t+S-1}\right)e_{i_{\varrho_t-1}}} \geq \frac{\delta}{2}$, 
		which then leads to
		\begin{equation*}
			\norm{y_1}\geq \frac{\delta}{2}\bigl\lvert e_{i_{\varrho_t-1}}^{\top} \nabla f(x_{\varrho_t-1})\bigr\rvert=:\frac{2r}{\epsilon(\alpha_{\max}-\alpha_{\min})}.
		\end{equation*}
		Thus, the set of $\alpha_{\varrho_t-1}$ such that $\alpha_{\varrho_t -1} y_1 \in \mathcal{B}_r(y_2)$ consists of an interval $J$ in $\bR$ with $\|\sup(J)\cdot y_1 - \inf(J)\cdot y_1\|\leq 2r$ as the diameter of $\mathcal{B}_r(y_2)$ is $2r$, which implies $m(J)\leq 2r/\norm{y_1}\leq \epsilon(\alpha_{\max}-\alpha_{\min})$. The lemma is proved then by setting $I=[\alpha_{\max}-\alpha_{\min}]\backslash J$.
	\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm: local-growth}]
		Without loss of generality, we will assume $t=0$ in the proof to simplify notation.
		Since $H=\nabla^2 f(x^*)$ is non-degenerate, we can take a neighborhood 
		$U$ of $x^*=0$ and some fixed $\sigma > 0$ such that
		\begin{equation}\label{eq: sigma}
			\norm{\nabla f(x)}\geq \sigma\norm{x},\quad \forall\ x\in U.    
		\end{equation}
		Assumption~\ref{Assump: Hess_bdd} implies that
		\begin{equation*}
			\norm{\nabla f(x)}=\norm{\nabla f(x)-\nabla f(x^*)}\leq M\norm{x-x^*}=M\norm{x},\quad\forall\ x\in\bR^d.
		\end{equation*}
		Using the above inequality and $\alpha_{\max}<1/M$, it holds for every $\omega\in\Omega$ and $t'\in\bN$ that 
		\begin{equation}\label{r-minus}
			\begin{split}
				\norm{x_{t'+1}}&=\norm{x_{t'}-\alpha_{t'} e_{i_{t'}}e_{i_{t'}}^{\top}\nabla f(x_{t'})} \\
				& \geq \norm{x_{t'}}-\alpha_{t'}\norm{e_{i_{t'}}e_{i_{t'}}^{\top}}\cdot \norm{\nabla f(x_{t'})}\\
				&\geq (1-M\alpha_{\max})\norm{x_{t'}},
			\end{split}
		\end{equation}
		and similarly that
		\begin{equation*}
			\norm{x_{t'+1}}\leq(1+M\alpha_{\max})\norm{x_{t'}}.
		\end{equation*}
		We thus define
		\begin{equation*}
			r_-:=1-M\alpha_{\max}\quad\text{and}\quad r_+:=1+M\alpha_{\max}, 
		\end{equation*}
		so that
		\begin{equation}\label{eq:compareiterate}
			r_- \norm{x_{t'}} \leq \norm{x_{t'+1}} \leq r_+ \norm{x_{t'}}.
		\end{equation}

		We now choose the time duration $S$ large enough in the finite block analysis to guarantee significant amplification. More specifically, we choose $S$ so large that $S \geq S_*$ ($S_*$ defined in Lemma~\ref{lem: T-Omega2}) and that the following two inequalities hold: 
		\begin{equation}\label{large S1}
			\exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{L-1}(\alpha_{\max}-\alpha_{\min})}{8}\geq
			(r_+)^{L},
		\end{equation}
		and
		\begin{equation}\label{large S2}
			(1-6\epsilon)\left(S(\lambda_+-\gamma)+\log \frac{\epsilon\delta \mu\sigma (r_-)^{2(L-1)}(\alpha_{\max}-\alpha_{\min})}{8}\right)+6\epsilon(L+S)\log r_->0,
		\end{equation}
		where $L$ is the upper bound defined in Lemma~\ref{lem: L}, $\mu\leq 1/\sqrt{d}$ is a fixed constant as in Lemma~\ref{lem: L}, $\delta$ is from Lemma~\ref{lem: Omega1}, and $\sigma$ is set in \eqref{eq: sigma}. 
		Thanks to \eqref{def: eps} for our choice of $\epsilon$ and that $\gamma < \lambda_+$ from \eqref{lambplus-gamma}, 
		\eqref{large S1} and \eqref{large S2} are satisfied for sufficiently large $S$. 

		Next, we show that, for any $S$ sufficiently large as above, there exists a convex neighborhood $U_1\subset U$ of $x^*=0$, such that for any $t'\in\bN$, any $x_{t'}\in U_1$, and any $(i,\alpha)_{t':t'+S-1}$, it holds that
		\begin{equation}\label{block-error}
			\norm{x_{t'+S}} \geq \norm{\Phi^H\bigl((i,\alpha)_{t':t'+S-1}\bigr)x_{t'}}-\norm{x_{t'}}.
		\end{equation}
		We first define a convex neighborhood $U_0 \subset U$ of $x^*=0$ such that
		\begin{multline*}
			\norm{\left(x-\alpha e_i e_i^{\top}\nabla f(x)\right)-\left(I-\alpha e_i e_i^{\top}H\right)x}=\norm{\alpha e_i e_i^{\top}\left(\nabla f(x)-H x\right)}\\
			=\norm{\alpha e_i e_i^{\top}\int_0^1 (\nabla^2 f(\eta x)-Hx) \mathrm{d} \eta}\leq \frac{1}{S(r_+)^{S-1}} \norm{x},
		\end{multline*}
		for any $x \in U_0$, any $i\in\{1,2,\dots,d\}$, and any $\alpha\in[\alpha_{\min},\alpha_{\max}]$.
		Applying the inequality $S$ times for $x_{t'}\in U_1 = (r_+)^{-(S-1)}U_0$, we have,
		\begin{equation*}
			\begin{split}
				&\norm{x_{t'+S}-\Phi^H\bigl((i,\alpha)_{t':t'+S-1}\bigr)x_{t'}}\\
				\leq & \norm{x_{t'+S}-\left(I-\alpha_{t'+S-1} e_{i_{t'+S-1}}e_{i_{t'+S-1}}^{\top}H\right)x_{t'+S-1}}\\
				&+\norm{I-\alpha_{t'+S-1} e_{i_{t'+S-1}}e_{i_{t'+S-1}}^{\top}H}\cdot \norm{x_{t'+S-1}-\Phi^H\bigl((i,\alpha)_{t':t'+S-2}\bigr)x_{t'}}\\
				\leq & \frac{1}{S(r_+)^{S-1}} \norm{x_{t'+S-1}}+r_+\norm{x_{t'+S-1}-\Phi^H\bigl((i,\alpha)_{t':t'+S-2}\bigr)x_{t'}}\\
				\leq& \frac{1}{S(r_+)^{S-1}} \left(\norm{x_{t'+S-1}}+r_+\norm{x_{t'+S-2}}+\cdots+(r_+)^{S-1}\norm{x_{t'}}\right)\\
				\leq& \norm{x_{t'}},
			\end{split}
		\end{equation*}
		and hence, inequality \eqref{block-error}.

		Setting $V=(r_+)^{-(L-1)} U_1$, we then have $x_{\varrho_0-1}\in U$ for any $x_0\in V$, which implies that $\norm{\nabla f(x_{\varrho_0-1})}\geq\sigma\norm{x_{\varrho_0-1}}$ as $\varrho_0\leq L$. 
		According to Lemma~\ref{lem: L}--\ref{lem: nontrial-proj}, for any given $x_0\in V$, with probability at least $1-4\epsilon$, we have $(i,\alpha)_{\varrho_0:\varrho_0+S-1}\in\Omega^S$, and  the followings hold:
		\begin{align}
			\label{ineq1} & \bigl\lvert e_{i_{\varrho_0-1}}^{\top} \nabla f(x_{\varrho_0-1})\bigr\rvert\geq \mu\norm{\nabla f(x_{\varrho_0-1})}, \\
			\label{ineq2} & \norm{\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}}\geq \frac{\epsilon\delta (\alpha_{\max}-\alpha_{\min})}{4}\bigl\lvert e_{i_{\varrho_0-1}}^{\top} \nabla f(x_{\varrho_0-1})\bigr\rvert,
		\end{align}
		where the probability is the marginal probability on $(i,\alpha)_{0:L+S-1}\in\Omega_0\times\cdots\times \Omega_{L+S-1}$.  

		\smallskip 

		Recall $\lambda_+$ and $\gamma$ in \eqref{lambplus-gamma}, and $d_+=\sum_{\lambda_i>0}d_i$. 
		It follows from \eqref{close: singular value} of the construction of the set $\Omega^S$ that
		\begin{equation*}
			\frac{1}{S}\log s_j\left(\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\right)\geq \lambda_{\mu(j)}-\gamma\geq \lambda_+-\gamma,\quad\forall\ j\leq d_+.
		\end{equation*}
		This is to say that the $d_+$ largest singular values of $\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)$
		are all greater than or equal to $\exp(S(\lambda_+-\gamma))$. 
		Therefore, it holds that 
		\begin{equation}\label{linear-growth}
			\begin{split}
				\norm{\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}}&\geq \norm{\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}}\\
				&  \leftstackrel{\eqref{ineq2}}{\geq} \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta (\alpha_{\max}-\alpha_{\min})}{4}\bigl\lvert e_{i_{\varrho_0-1}}^{\top} \nabla f(x_{\varrho_0-1})\bigr\rvert\\
				&  \leftstackrel{\eqref{ineq1}}{\geq}
				\exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta\mu (\alpha_{\max}-\alpha_{\min})}{4}\norm{\nabla f(x_{\varrho_0-1})},
			\end{split}
		\end{equation}
		where the first inequality follows from the fact that $\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}$ and $\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\left(I-\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\right)x_{\varrho_0}$ are orthogonal. Combining \eqref{block-error} and \eqref{linear-growth}, we obtain that
		\begin{equation*}
			\begin{split}
				\norm{x_{\varrho_0+S}} & \geq \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu(\alpha_{\max}-\alpha_{\min})}{4}\norm{\nabla f(x_{\varrho_0-1})}-\norm{x_{\varrho_0}}\\
				& \leftstackrel{\eqref{eq:compareiterate}}{\geq} \left(\exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{L-1}(\alpha_{\max}-\alpha_{\min})}{4}-(r_+)^{L}\right)\cdot\norm{x_0}\\
				& \leftstackrel{\eqref{large S1}}{\geq} \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{L-1}(\alpha_{\max}-\alpha_{\min})}{8}\cdot\norm{x_0}.
			\end{split}
		\end{equation*}
		Therefore, it holds that
		\begin{equation*}
			\begin{aligned}
				\norm{x_{L+S}} & \; \leftstackrel{\eqref{eq:compareiterate}}{\geq} (r_-)^{L-1} \norm{x_{\varrho_0+S}} \\
				& \; \geq \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{2(L-1)}(\alpha_{\max}-\alpha_{\min})}{8}\cdot\norm{x_0}.
			\end{aligned}
		\end{equation*}
		We finally arrive at \eqref{local-growth} by setting $T = L + S$ and combining the above with \eqref{large S2}.
	\end{proof}

\begin{theorem}\label{thm: single-pt}
		Suppose that Assumption~\ref{Assump: Hess_bdd}, \ref{Assump: non-degenerate}, and \ref{Assump: non-zero-proj} hold and that $0<\alpha_{\min}<\alpha_{\max}<1/M$. Then for every $x^*\in\calA$ 
		and every $x_0\in\bR^d\backslash\{x^*\}$, it holds that
		\begin{equation*}
			\bP(\calC(x^*,x_0))=0.
		\end{equation*}
	\end{theorem}

\begin{proof}
		Without loss of generality, we assume that $x^*=0$. Conditioned on $\mathcal{F}_{t-1}$ with $x_t\in V$, where $V$ can be assumed to be bounded, Theorem~\ref{thm: local-growth} states that with probability at least $1-4\epsilon$, 
		\begin{equation*}
			\norm{x_{t+T}} \geq A \norm{x_t},
		\end{equation*}
		where to simplify notation we denote 
		\begin{equation*}
			A := \exp\biggl(\frac{6\epsilon}{1 - 6 \epsilon} \bigl\lvert \log(1-M\alpha_{\max}) \bigr\rvert \, T\biggr)
		\end{equation*}
		the amplification factor appearing on the right-hand side of \eqref{local-growth}. 
		Notice also that, due to \eqref{eq:compareiterate}, we always have
		\begin{equation*}
			\norm{x_{t+T}}\geq (r_-)^{T}\norm{x_t}.
		\end{equation*}
		It suffices to show that for any $x_0\in V\backslash\{x^*\}$, with probability $1$ there exists some $t\in\bNp$ such that $x_t\notin V$.

		Let us consider the iterates every $T$ steps: Denote $y_t=x_{T t}$ and $\mathcal{G}_t=\mathcal{F}_{T t-1}$ for $t\in\bN$. Denote stopping time
		\begin{equation*}
			\rho=\inf\{t\in\bN:y_t\notin V\},
		\end{equation*}
		it suffices to show that $\bP(\rho<\infty)=1$. We define a sequence of random variables $I_t$ as follows:
		\begin{equation*}
			I_t(\omega)=\begin{cases}1,&\text{if }\norm{y_{t+1}}\geq A\norm{y_t},\\
				0,&\text{otherwise}.\end{cases}
		\end{equation*}
		By the discussion in the beginning of the proof, we have  
		\begin{equation*}
			\bP(I_t = 1\ |\ \mathcal{G}_t, t<\rho)\geq 1-4\epsilon,
		\end{equation*}
		and moreover, setting $S_t(\omega)=\sum_{0\leq s<t} I_t(\omega)$, we have for $t<\rho(\omega)$,
		\begin{equation*}
			\frac{\norm{y_t}}{\norm{y_0}} \geq A^{S_t(\omega)} \cdot (r_-)^{T(t-S_t(\omega))}.
		\end{equation*}
		Denote $R:=\sup_{x\in V}\norm{x}<\infty$. Since  $(1-5\epsilon)\log A+5\epsilon T\log r_->0$, there exists $t_*\in\bN$, such that
		\begin{equation*}
			\left(A^{1-5\epsilon}\cdot (r_-)^{5\epsilon T}\right)^t>\frac{R}{\norm{y_0}},\quad\forall\ t\geq t_*.
		\end{equation*}
		Therefore, for any $t\geq t_*$, it holds that 
		\begin{equation*}
			\bP(\rho> t) = \bP\bigl(\rho> t,S_t\leq (1-5\epsilon)t\bigr)\leq \sum_{i\leq (1-5\epsilon)t} \binom{t}{i} (1-4\epsilon)^i (4\epsilon)^{t-i}.
		\end{equation*}
		As we will show in the next lemma that the right-hand side of above goes to $0$ as $t \to \infty$, and thus $\lim_{t\rightarrow\infty}\bP(\rho> t)=0$, which implies that $\bP(\rho<\infty)=1$.
	\end{proof}

\begin{lemma}\label{lem: binomial}
		For any $\epsilon\in(0,1/4)$, it holds that
		\begin{equation*}
			\lim_{t\rightarrow\infty}\sum_{i\leq(1-5\epsilon)t} \binom{t}{i} (1-4\epsilon)^i (4\epsilon)^{t-i}=0.
		\end{equation*}
	\end{lemma}

\begin{proof}
		Let $X_0,X_1,X_2,\dots$ be a sequence of i.i.d. random variables with $X_i$ being a Bernoulli random variable with expectation $1-4\epsilon$. Denote the average $\bar{X}_t=\frac{1}{t} \sum_{0\leq s<t} X_s$. The weak law of large numbers yields that
		\begin{equation*}
			\sum_{i\leq(1-5\epsilon)t} \binom{t}{i} (1-4\epsilon)^i (4\epsilon)^{t-i}=\bP\left(\bar{X}_t\leq 1-5\epsilon\right)\leq \bP\left(|\bar{X}_t-\bE X_0|\geq \epsilon\right)\rightarrow 0,
		\end{equation*}
		as $t\rightarrow\infty$.
	\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm: main}]
		Assumption~\ref{Assump: non-degenerate} guarantees that, in a small neighborhood of $x^*$, the gradient $\nabla f(x)=\nabla^2 f(x^*)(x-x^*)+o(\norm{x-x^*})$ is non-vanishing as long as $x\neq x^*$, which implies that $x^*$ is an isolated stationary point. Therefore, $\calA$ is countable. Then Theorem~\ref{thm: main} follows directly from Theorem~\ref{thm: single-pt} and the countability of $\calA$.
	\end{proof}

