\begin{proof}[Proof of Proposition~\ref{prop: posi-lamb1}] It suffices to show that for almost every $\omega\in\Omega$ there exist some $x_0\in \bR^d$, $\epsilon>0$, and $T>0$, such that $x_t=\Phi(t,\omega)x_0$ satisfies $\norm{x_t}\geq e^{\epsilon t}$ for any $t>T$. Let $x_0$ be an eigenvector corresponding to a negative eigenvalue of $H$. Then it holds that $f^H(x_0)< 0$. Consider a fixed $m\geq d$. For any $k\in\bN$, set $I_k=1$ if $\{1,2,\dots,d\}=\{i_{km},i_{km+1},\dots,i_{km+m-1}\}$ 
		and $I_k=0$ otherwise. We can see that the random variables, $I_0,I_1,I_2,\dots$, are independent and identically distributed with $\bE I_0=\bP(I_0=1)\in(0,1)$. By Proposition~\ref{prop: linear_decay}, we obtain that
		\begin{equation*}
			f^H(x_{(k+1)m})\leq\begin{cases}
				(1+c)f^H(x_{km}),&\text{if }I_k=1,\\
				f^H(x_{km}),&\text{if }I_k=0,
			\end{cases}
		\end{equation*}	
		where $c$ is the constant from Proposition~\ref{prop: linear_decay}.
		Therefore, %\jl{missing $1/2$}
		\begin{equation*}
			\frac{\lambda_{\min}(H)}{2}\norm{x_{km}}^2\leq f^H(x_{km})\leq(1+c)^{\sum_{j=0}^{k-1} I_j}f^H(x_0),
		\end{equation*}
		which implies that
		\begin{equation}\label{norm:xkm}
			\norm{x_{km}}\geq \left(\frac{2f^H(x_0)}{\lambda_{\min}(H)}\right)^{1/2}\cdot (1+c)^{\frac{1}{2}\sum_{j=0}^{k-1} I_j}.
		\end{equation}
		Note that $\bE |I_0|=\bE I_0<\infty$. The strong law of large number suggests that for almost every $\omega\in\Omega$, there exists some $K$, such that for all $k \geq K$
		\begin{equation}\label{SLLN}
			\sum_{j=0}^{k-1} I_j\geq \frac{\bE I_0}{2}k.
		\end{equation}
		Combining \eqref{norm:xkm} and \eqref{SLLN}, we arrive at
		\begin{equation*}
			\norm{x_{km}}\geq \left(\frac{2f^H(x_0)}{\lambda_{\min}(H)}\right)^{1/2}\cdot (1+c)^{\frac{\bE I_0}{4m}\cdot km}.
		\end{equation*}
		Noticing that $(1+c)^{\frac{\bE I_0}{4m}}$ is greater than $1$, $\norm{x_{km}}$ grows exponentially in $km$ and we complete the proof.
	\end{proof}

