\begin{proposition}\label{prop: linear_decay}
		Let $m\geq d$ be fixed. For the objective function \eqref{obj: quadratic} with $\lambda_{\min}(H)<0$, suppose 
		that $0<\alpha_{\min}<\alpha_{\max}<1/\max_{1\leq i\leq d}|H_{ii}|$, there exists $c\in(0,1)$ depending on $m$, $H$, $\alpha_{\min}$, and $\alpha_{\max}$, 
		such that 
		\begin{equation*}
			f^H(x_{t+m})-f^H(x_t)\leq c\, f^H(x_t),
		\end{equation*}
		holds as long as $f^H(x_t)<0$ and $\{1,2,\dots,d\}=\{i_t,i_{t+1},\dots,i_{t+m-1}\}$ (in the sense of sets). 
	\end{proposition}

\begin{proof} 
		Without loss of generality, we assume that $t=0$. 
		Due to the choice of $\alpha_{\max}$, we have the following simple non-increasing property for any $t'\in\bN$:
		\begin{equation}\label{decay: quad}
			\begin{split}
				f^H(x_{t'+1})&=\frac{1}{2}x_{t'+1}^{\top} H x_{t'+1}\\
				&=\frac{1}{2}x_{t'}^{\top} \left(I-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H\right)^{\top} H \left(I-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H\right) x_{t'}\\
				&=f^H(x_{t'})-\alpha_{t'} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2+\frac{1}{2}\alpha_t^2 e_{i_{t'}}^{\top} H e_{i_{t'}} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2\\
				&\leq f^H(x_{t'})-\frac{\alpha_{t'}}{2} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2.
			\end{split}
		\end{equation}

		Write $x_0=y^*+y_0$ with $y^*\in\ker(H)$ and $y_0\in\ran(H)$. Let 
		\begin{equation}
			\label{def: y}
			y_{t'+1}=y_{t'}-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H y_{t'}, \qquad t'=0,1,\dots,m-1.
		\end{equation} 
		Then $x_{t'}=y^*+y_{t'}$ holds for any $t'=0,1,\dots,m$. Using \eqref{decay: quad}, to give an upper bound for $f^H(x_{t+m})-f^H(x_t)$, we would like a nontrivial lower bound for $\alpha_{t'}\bigl(e_{i_{t'}}^{\top} H x_{t'}\bigr)^2=\alpha_{t'}\bigl(e_{i_{t'}}^{\top} H y_{t'}\bigr)^2$ for some $t'\in\{t,t+1,\dots,t+m-1\}$, which is guaranteed by Lemma~\ref{lem: linear_decay}, whose proof will be postponed.

	Assuming the lemma, there exists $T\in\{0,1,\dots,m-1\}$ that 
	\begin{equation*}
		\alpha_T\left\vert e_{i_{T}}^{\top} H y_{T}\right\vert\geq \delta\norm{y_{T}},
	\end{equation*}
	with a fixed $\delta>0$ satisfying \eqref{def:delta}. We can further constrain that $\frac{\delta^2}{\alpha_{\min}\sigma_{\max}(H)}<1$. Thus, we have
	\begin{equation*}\label{decay esti}
		\begin{split}
			f^H(x_m)&\leq f^H (x_{T+1})\leq f^H(x_T)- \frac{\alpha_T}{2}\left(e_{i_{T}}^{\top} H x_{T}\right)^2\leq f^H (x_{T}) -\frac{\delta^2}{2\alpha_T}\norm{y_{T}}^2,
		\end{split}
	\end{equation*}
	which combined with $\sigma_{\max}(H)\norm{y_{T}}^2\geq -y_{T}^{\top} H y_{T}=-x_{T}^{\top} H x_{T}=-2f^H(x_T)$,
	yields that 
	\begin{equation*}
		f^H (x_m) \leq\left( 1 +\frac{\delta^2}{\alpha_T \sigma_{\max}(H)}\right)f^H (x_{T}) \leq\left( 1 +\frac{\delta^2}{\alpha_T \sigma_{\max}(H)}\right)f^H (x_0). 
	\end{equation*}
	Set $c=\frac{\delta^2}{\alpha_{\max} \sigma_{\max}(H)}$ and we get that $f^H(x_m)-f^H(x_0)\leq c f^H(x_0)$.
\end{proof}

Without loss of generality, we assume that $t=0$. 
Due to the choice of $\alpha_{\max}$, we have the following simple non-increasing property for any $t'\in\bN$:
\begin{equation}\label{decay: quad}
	\begin{split}
		f^H(x_{t'+1})&=\frac{1}{2}x_{t'+1}^{\top} H x_{t'+1}\\
		&=\frac{1}{2}x_{t'}^{\top} \left(I-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H\right)^{\top} H \left(I-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H\right) x_{t'}\\
		&=f^H(x_{t'})-\alpha_{t'} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2+\frac{1}{2}\alpha_t^2 e_{i_{t'}}^{\top} H e_{i_{t'}} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2\\
		&\leq f^H(x_{t'})-\frac{\alpha_{t'}}{2} \left(e_{i_{t'}}^{\top} H x_{t'}\right)^2.
	\end{split}
\end{equation}

Write $x_0=y^*+y_0$ with $y^*\in\ker(H)$ and $y_0\in\ran(H)$. Let 
\begin{equation}
	\label{def: y}
	y_{t'+1}=y_{t'}-\alpha_{t'} e_{i_{t'}} e_{i_{t'}}^{\top} H y_{t'}, \qquad t'=0,1,\dots,m-1.
\end{equation} 
Then $x_{t'}=y^*+y_{t'}$ holds for any $t'=0,1,\dots,m$. Using \eqref{decay: quad}, to give an upper bound for $f^H(x_{t+m})-f^H(x_t)$, we would like a nontrivial lower bound for $\alpha_{t'}\bigl(e_{i_{t'}}^{\top} H x_{t'}\bigr)^2=\alpha_{t'}\bigl(e_{i_{t'}}^{\top} H y_{t'}\bigr)^2$ for some $t'\in\{t,t+1,\dots,t+m-1\}$, which is guaranteed by Lemma~\ref{lem: linear_decay}, whose proof will be postponed.

Assuming the lemma, there exists $T\in\{0,1,\dots,m-1\}$ that 
\begin{equation*}
	\alpha_T\left\vert e_{i_{T}}^{\top} H y_{T}\right\vert\geq \delta\norm{y_{T}},
\end{equation*}
with a fixed $\delta>0$ satisfying \eqref{def:delta}. We can further constrain that $\frac{\delta^2}{\alpha_{\min}\sigma_{\max}(H)}<1$. Thus, we have
\begin{equation*}\label{decay esti}
	\begin{split}
		f^H(x_m)&\leq f^H (x_{T+1})\leq f^H(x_T)- \frac{\alpha_T}{2}\left(e_{i_{T}}^{\top} H x_{T}\right)^2\leq f^H (x_{T}) -\frac{\delta^2}{2\alpha_T}\norm{y_{T}}^2,
	\end{split}
\end{equation*}

which combined with $\sigma_{\max}(H)\norm{y_{T}}^2\geq -y_{T}^{\top} H y_{T}=-x_{T}^{\top} H x_{T}=-2f^H(x_T)$,
yields that 
\begin{equation*}
	f^H (x_m) \leq\left( 1 +\frac{\delta^2}{\alpha_T \sigma_{\max}(H)}\right)f^H (x_{T}) \leq\left( 1 +\frac{\delta^2}{\alpha_T \sigma_{\max}(H)}\right)f^H (x_0). 
\end{equation*}
Set $c=\frac{\delta^2}{\alpha_{\max} \sigma_{\max}(H)}$ and we get that $f^H(x_m)-f^H(x_0)\leq c f^H(x_0)$.

\begin{lemma} \label{lem: linear_decay}
			Suppose that $\{1,2,\dots,d\}=\{i_0,i_1,\dots,i_{m-1}\}$. For any
			\begin{equation}\label{def:delta}
				0<\delta\leq\min\left\{\frac{1}{2m},\frac{\alpha_{\min}\sigma_{\min}(H)}{2\sqrt{m}(m\alpha_{\max}\sigma_{\max}(H)+1)}\right\},
			\end{equation}
			where $\sigma_{\min}(H)$ and $\sigma_{\max}(H)$ are the smallest and largest positive singular values of $H$ respectively, 
			if $0\neq y_0\in \ran(H)$, then there exists $T\in \{0,1,\dots,m-1\}$ such that $\alpha_{T}\left\vert e_{i_{T}}^{\top} H y_{T}\right\vert\geq \delta\norm{y_{T}}$, where the sequence $y_t$ is given as in \eqref{def: y}. 
		\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem: linear_decay}] Suppose on the contrary that $\alpha_t\left\vert e_{i_t}^{\top} H y_t\right\vert< \delta\norm{y_t}$ for any $t\in \{0,1,\dots,m-1\}$. It holds that
		\begin{equation*}
			\norm{y_1-y_0}=\alpha_0\left\vert e_{i_0}^{\top} H y_0\right\vert<\delta\norm{y_0}<2\delta\norm{y_0}.
		\end{equation*}
		We claim that 
		\begin{equation} \label{eq: disty}
			\norm{y_t-y_0}<2 t\delta\norm{y_0},
		\end{equation}
		for any $t=1,2,\dots,m-1$. By induction, assume that  $\norm{y_t-y_0}<2t\delta\norm{y_0}$ holds for some $t\in\{1,2,\dots,m-2\}$, then 
		\begin{equation*}
			\norm{y_{t+1}-y_t}=\alpha_t\left\vert e_{i_t}^{\top} H y_t\right\vert< \delta\norm{y_t}<\delta(2t\delta+1)\norm{y_0}<2\delta\norm{y_0},
		\end{equation*}
		where the last inequality uses $2 t \delta < 2m \delta \leq 1 $. It follows $\norm{y_{t+1}-y_0}\leq \norm{y_t-y_0}+\norm{y_{t+1}-y_t}<2(t+1)\delta\norm{y_0}$.

		Using \eqref{eq: disty} and $\max_{1\leq i\leq d} \norm{H e_i}\leq \sigma_{\max}(H)$, we have 
		\begin{equation*}
			\begin{split}
				\alpha_t\bigl\lvert e_{i_t}^{\top} H y_0\bigr\rvert&\leq \alpha_t\bigl\lvert e_{i_t}^{\top} H (y_t-y_0)\bigr\rvert+\alpha_t\bigl\lvert e_{i_t}^{\top} H y_t\bigr\rvert\\
				&<\alpha_{\max}\sigma_{\max}(H)\cdot 2 t\delta\norm{y_0}+2\delta\norm{y_0}\\
				&<2\delta(m\alpha_{\max}\sigma_{\max}(H)+1)\norm{y_0},
			\end{split}
		\end{equation*}
		for $t=0,1,\dots,m-1$. Since $\text{span}\{e_{i_k}:k=0,1,\dots,m-1\}=\bR^d$, noticing that $y_0\in\ran{H}$, we have
		\begin{equation*}
			\begin{split}
				\alpha_{\min}\sigma_{\min}(H) \norm{y_0}&\leq \alpha_{\min}\norm{H y_0}\leq\left(\sum_{t=0}^{m-1} \left(\alpha_t\bigl\lvert e_{i_t}^{\top} H y_0\bigr\rvert\right)^2\right)^{1/2}\\
				& <2\delta\sqrt{m}(m\alpha_{\max}\sigma_{\max}(H)+1)\norm{y_0},
			\end{split}
		\end{equation*}
		which contradicts with the choice of $\delta$ in \eqref{def:delta}.
	\end{proof}

Using \eqref{eq: disty} and $\max_{1\leq i\leq d} \norm{H e_i}\leq \sigma_{\max}(H)$, we have 
\begin{equation*}
	\begin{split}
		\alpha_t\bigl\lvert e_{i_t}^{\top} H y_0\bigr\rvert&\leq \alpha_t\bigl\lvert e_{i_t}^{\top} H (y_t-y_0)\bigr\rvert+\alpha_t\bigl\lvert e_{i_t}^{\top} H y_t\bigr\rvert\\
