		& <2\delta\sqrt{m}(m\alpha_{\max}\sigma_{\max}(H)+1)\norm{y_0},
	\end{split}
\end{equation*}
which contradicts with the choice of $\delta$ in \eqref{def:delta}.

\begin{theorem}\label{thm: local-growth}
		Suppose that Assumptions~\ref{Assump: Hess_bdd}, \ref{Assump: non-degenerate}, and \ref{Assump: non-zero-proj} hold and that $0<\alpha_{\min}<\alpha_{\max}<1/M$. There exists $\epsilon_*\in(0,1/6)$ such that for any $\epsilon\in(0,\epsilon_*)$, we have $T_* = T_*(\epsilon) \in\bNp$ that for any $T \in \bNp$ with $T\geq T_*$ and any $t\in\bN$, conditioned on $\mathcal{F}_{t-1}$, with probability at least $1-4\epsilon$, it holds for all $x_t \in V$ that
		\begin{equation}\label{local-growth}
			\norm{x_{t+T}}\geq \exp\biggl(\frac{6\epsilon}{1 - 6 \epsilon} \bigl\lvert \log(1-M\alpha_{\max}) \bigr\rvert \, T\biggr) \norm{x_t},
		\end{equation}
		where $V$ is a neighborhood of $x^* = 0$, depending on $\epsilon$, $T$, and $f$ near $x^*$. 
	\end{theorem}

\begin{proof}[Proof of Theorem~\ref{thm: local-growth}]
		Without loss of generality, we will assume $t=0$ in the proof to simplify notation.
		Since $H=\nabla^2 f(x^*)$ is non-degenerate, we can take a neighborhood 
		$U$ of $x^*=0$ and some fixed $\sigma > 0$ such that
		\begin{equation}\label{eq: sigma}
			\norm{\nabla f(x)}\geq \sigma\norm{x},\quad \forall\ x\in U.    
		\end{equation}
		Assumption~\ref{Assump: Hess_bdd} implies that
		\begin{equation*}
			\norm{\nabla f(x)}=\norm{\nabla f(x)-\nabla f(x^*)}\leq M\norm{x-x^*}=M\norm{x},\quad\forall\ x\in\bR^d.
		\end{equation*}
		Using the above inequality and $\alpha_{\max}<1/M$, it holds for every $\omega\in\Omega$ and $t'\in\bN$ that 
		\begin{equation}\label{r-minus}
			\begin{split}
				\norm{x_{t'+1}}&=\norm{x_{t'}-\alpha_{t'} e_{i_{t'}}e_{i_{t'}}^{\top}\nabla f(x_{t'})} \\
				& \geq \norm{x_{t'}}-\alpha_{t'}\norm{e_{i_{t'}}e_{i_{t'}}^{\top}}\cdot \norm{\nabla f(x_{t'})}\\
				&\geq (1-M\alpha_{\max})\norm{x_{t'}},
			\end{split}
		\end{equation}
		and similarly that
		\begin{equation*}
			\norm{x_{t'+1}}\leq(1+M\alpha_{\max})\norm{x_{t'}}.
		\end{equation*}
		We thus define
		\begin{equation*}
			r_-:=1-M\alpha_{\max}\quad\text{and}\quad r_+:=1+M\alpha_{\max}, 
		\end{equation*}
		so that
		\begin{equation}\label{eq:compareiterate}
			r_- \norm{x_{t'}} \leq \norm{x_{t'+1}} \leq r_+ \norm{x_{t'}}.
		\end{equation}

		We now choose the time duration $S$ large enough in the finite block analysis to guarantee significant amplification. More specifically, we choose $S$ so large that $S \geq S_*$ ($S_*$ defined in Lemma~\ref{lem: T-Omega2}) and that the following two inequalities hold: 
		\begin{equation}\label{large S1}
			\exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{L-1}(\alpha_{\max}-\alpha_{\min})}{8}\geq
			(r_+)^{L},
		\end{equation}
		and
		\begin{equation}\label{large S2}
			(1-6\epsilon)\left(S(\lambda_+-\gamma)+\log \frac{\epsilon\delta \mu\sigma (r_-)^{2(L-1)}(\alpha_{\max}-\alpha_{\min})}{8}\right)+6\epsilon(L+S)\log r_->0,
		\end{equation}
		where $L$ is the upper bound defined in Lemma~\ref{lem: L}, $\mu\leq 1/\sqrt{d}$ is a fixed constant as in Lemma~\ref{lem: L}, $\delta$ is from Lemma~\ref{lem: Omega1}, and $\sigma$ is set in \eqref{eq: sigma}. 
		Thanks to \eqref{def: eps} for our choice of $\epsilon$ and that $\gamma < \lambda_+$ from \eqref{lambplus-gamma}, 
		\eqref{large S1} and \eqref{large S2} are satisfied for sufficiently large $S$. 

		Next, we show that, for any $S$ sufficiently large as above, there exists a convex neighborhood $U_1\subset U$ of $x^*=0$, such that for any $t'\in\bN$, any $x_{t'}\in U_1$, and any $(i,\alpha)_{t':t'+S-1}$, it holds that
		\begin{equation}\label{block-error}
			\norm{x_{t'+S}} \geq \norm{\Phi^H\bigl((i,\alpha)_{t':t'+S-1}\bigr)x_{t'}}-\norm{x_{t'}}.
		\end{equation}
		We first define a convex neighborhood $U_0 \subset U$ of $x^*=0$ such that
		\begin{multline*}
			\norm{\left(x-\alpha e_i e_i^{\top}\nabla f(x)\right)-\left(I-\alpha e_i e_i^{\top}H\right)x}=\norm{\alpha e_i e_i^{\top}\left(\nabla f(x)-H x\right)}\\
			=\norm{\alpha e_i e_i^{\top}\int_0^1 (\nabla^2 f(\eta x)-Hx) \mathrm{d} \eta}\leq \frac{1}{S(r_+)^{S-1}} \norm{x},
		\end{multline*}
		for any $x \in U_0$, any $i\in\{1,2,\dots,d\}$, and any $\alpha\in[\alpha_{\min},\alpha_{\max}]$.
		Applying the inequality $S$ times for $x_{t'}\in U_1 = (r_+)^{-(S-1)}U_0$, we have,
		\begin{equation*}
			\begin{split}
				&\norm{x_{t'+S}-\Phi^H\bigl((i,\alpha)_{t':t'+S-1}\bigr)x_{t'}}\\
				\leq & \norm{x_{t'+S}-\left(I-\alpha_{t'+S-1} e_{i_{t'+S-1}}e_{i_{t'+S-1}}^{\top}H\right)x_{t'+S-1}}\\
				&+\norm{I-\alpha_{t'+S-1} e_{i_{t'+S-1}}e_{i_{t'+S-1}}^{\top}H}\cdot \norm{x_{t'+S-1}-\Phi^H\bigl((i,\alpha)_{t':t'+S-2}\bigr)x_{t'}}\\
				\leq & \frac{1}{S(r_+)^{S-1}} \norm{x_{t'+S-1}}+r_+\norm{x_{t'+S-1}-\Phi^H\bigl((i,\alpha)_{t':t'+S-2}\bigr)x_{t'}}\\
				\leq& \frac{1}{S(r_+)^{S-1}} \left(\norm{x_{t'+S-1}}+r_+\norm{x_{t'+S-2}}+\cdots+(r_+)^{S-1}\norm{x_{t'}}\right)\\
				\leq& \norm{x_{t'}},
			\end{split}
		\end{equation*}
		and hence, inequality \eqref{block-error}.

		Setting $V=(r_+)^{-(L-1)} U_1$, we then have $x_{\varrho_0-1}\in U$ for any $x_0\in V$, which implies that $\norm{\nabla f(x_{\varrho_0-1})}\geq\sigma\norm{x_{\varrho_0-1}}$ as $\varrho_0\leq L$. 
		According to Lemma~\ref{lem: L}--\ref{lem: nontrial-proj}, for any given $x_0\in V$, with probability at least $1-4\epsilon$, we have $(i,\alpha)_{\varrho_0:\varrho_0+S-1}\in\Omega^S$, and  the followings hold:
		\begin{align}
			\label{ineq1} & \bigl\lvert e_{i_{\varrho_0-1}}^{\top} \nabla f(x_{\varrho_0-1})\bigr\rvert\geq \mu\norm{\nabla f(x_{\varrho_0-1})}, \\
			\label{ineq2} & \norm{\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}}\geq \frac{\epsilon\delta (\alpha_{\max}-\alpha_{\min})}{4}\bigl\lvert e_{i_{\varrho_0-1}}^{\top} \nabla f(x_{\varrho_0-1})\bigr\rvert,
		\end{align}
		where the probability is the marginal probability on $(i,\alpha)_{0:L+S-1}\in\Omega_0\times\cdots\times \Omega_{L+S-1}$.  

		\smallskip 

		Recall $\lambda_+$ and $\gamma$ in \eqref{lambplus-gamma}, and $d_+=\sum_{\lambda_i>0}d_i$. 
		It follows from \eqref{close: singular value} of the construction of the set $\Omega^S$ that
		\begin{equation*}
			\frac{1}{S}\log s_j\left(\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\right)\geq \lambda_{\mu(j)}-\gamma\geq \lambda_+-\gamma,\quad\forall\ j\leq d_+.
		\end{equation*}
		This is to say that the $d_+$ largest singular values of $\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)$
		are all greater than or equal to $\exp(S(\lambda_+-\gamma))$. 
		Therefore, it holds that 
		\begin{equation}\label{linear-growth}
			\begin{split}
				\norm{\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}}&\geq \norm{\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}}\\
				&  \leftstackrel{\eqref{ineq2}}{\geq} \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta (\alpha_{\max}-\alpha_{\min})}{4}\bigl\lvert e_{i_{\varrho_0-1}}^{\top} \nabla f(x_{\varrho_0-1})\bigr\rvert\\
				&  \leftstackrel{\eqref{ineq1}}{\geq}
				\exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta\mu (\alpha_{\max}-\alpha_{\min})}{4}\norm{\nabla f(x_{\varrho_0-1})},
			\end{split}
		\end{equation}
		where the first inequality follows from the fact that $\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)x_{\varrho_0}$ and $\Phi^H\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\left(I-\mathcal{P}^H_+\left((i,\alpha)_{\varrho_0:\varrho_0+S-1}\right)\right)x_{\varrho_0}$ are orthogonal. Combining \eqref{block-error} and \eqref{linear-growth}, we obtain that
		\begin{equation*}
			\begin{split}
				\norm{x_{\varrho_0+S}} & \geq \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu(\alpha_{\max}-\alpha_{\min})}{4}\norm{\nabla f(x_{\varrho_0-1})}-\norm{x_{\varrho_0}}\\
				& \leftstackrel{\eqref{eq:compareiterate}}{\geq} \left(\exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{L-1}(\alpha_{\max}-\alpha_{\min})}{4}-(r_+)^{L}\right)\cdot\norm{x_0}\\
				& \leftstackrel{\eqref{large S1}}{\geq} \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{L-1}(\alpha_{\max}-\alpha_{\min})}{8}\cdot\norm{x_0}.
			\end{split}
		\end{equation*}
		Therefore, it holds that
		\begin{equation*}
			\begin{aligned}
				\norm{x_{L+S}} & \; \leftstackrel{\eqref{eq:compareiterate}}{\geq} (r_-)^{L-1} \norm{x_{\varrho_0+S}} \\
				& \; \geq \exp(S(\lambda_+-\gamma))\cdot \frac{\epsilon\delta \mu\sigma (r_-)^{2(L-1)}(\alpha_{\max}-\alpha_{\min})}{8}\cdot\norm{x_0}.
			\end{aligned}
		\end{equation*}
		We finally arrive at \eqref{local-growth} by setting $T = L + S$ and combining the above with \eqref{large S2}.
	\end{proof}

